insert into public.jobs(id,organization_id,kind) values ('00000700-0000-0000-0000-000000000001','00000100-0000-0000-0000-000000000001','import');
set local role service_role;
select ok(((public.claim_job('worker',array['revert_import'])).id is null),'filtra kind');
select ok(((public.claim_job('worker',array['import'])).id = '00000700-0000-0000-0000-000000000001'::uuid),'reclama job');
select ok((select status='running' and attempts=1 and locked_by='worker' and locked_at is not null from public.jobs where id='00000700-0000-0000-0000-000000000001'),'claim fija bloqueo e intento');
select ok(((public.claim_job('otro',array['import'])).id is null),'no reclama running');
select throws_ok($$select public.complete_job('00000700-0000-0000-0000-000000000001','queued',null)$$,'22023',null::text,'rechaza estado no terminal');
select ok(((public.complete_job('00000700-0000-0000-0000-000000000001','failed','error')).status='queued'),'reintenta fallo');
