select ok(((public.complete_job('00000700-0000-0000-0000-000000000001','failed','final')).status='failed'),'agota intentos');
select ok((select finished_at is not null from public.jobs where id='00000700-0000-0000-0000-000000000001'),'fallo terminal fechado');
insert into public.jobs(kind,attempts,max_attempts) values ('import',3,3);
