insert into public.jobs(kind) values ('revert_import');
select ok(((public.claim_job('w',array['revert_import'])).status='running'),'reclama reversion');
select ok((select (public.complete_job(id,'done',null)).status='done' from public.jobs where status='running'),'completa correctamente');
